/**
 * Create a foreign ID column for the given model.
 *
 * @param  \Illuminate\Database\Eloquent\Model|string  $model
 * @param  string|null  $column
 * @return \Illuminate\Database\Schema\ForeignIdColumnDefinition
 */
public function foreignIdFor($model, $column = null)
{
    if (is_string($model)) {
        $model = new $model;
    }

    $keyType = $model->getKeyType();
    $incrementing = $model->getIncrementing();
    $relatedTable = (new Stringable($model->getTable()))->trim()->toString();
    $keyName = $model->getKeyName();
    $usesUniqueIds = $model->usesUniqueIds();
    $uniqueIdItems = (new Collection($model->uniqueIds()))->all();
    $keyIsUniqueString = $usesUniqueIds && in_array($keyName, $uniqueIdItems, true);

    $column = $column ?: $model->getForeignKey();

    $reference = new ForeignKeyDefinition([
        'on' => $relatedTable,
        'references' => [$keyName],
    ]);

    $modelTraits = class_uses_recursive($model);
    $usesUlids = in_array(HasUlids::class, $modelTraits, true);

    if ($keyType === 'int' && $incrementing && ! $keyIsUniqueString) {
        $this->foreignId($column);
    } elseif ($usesUlids) {
        $this->foreignUlid($column, 26);
    } else {
        $this->foreignUuid($column);
    }

    $definition = $this->columns[array_key_last($this->columns)];

    if ($definition->getBlueprint() === $this && $definition->name === $column && $definition->type) {
        $definition->table($reference->on)
            ->referencesModelColumn($reference->references[0]);
    }

    return $definition;
}

